-- cn35_rune_hunt: 常驻日常符文本（RUNE350-03）。
--
-- 设计真源：用户附件 rune-hunt-2026-10-03.md（record_key=resource-rune-hunt-01）。
-- 要点：
--   - stage 902 符文本 tab（与素材/金币本同 extra_stages 入口），area 9007，
--     三档 quest 90701-90703（AP 10/20/30，exp 300/600/900，initial_power=4000）。
--   - 单波 155 只：5 节奏段各 1 王宠+30 小怪；王宠时点 0/42/84/126/168s，
--     小怪王宠后 8s 起每 1.1s；末怪 207.9s。powerup_rate=1.0。
--   - 掉落为新 reward 域 cn35_resource_quest_rune_drops：小怪/王宠独立
--     基础概率 + 四档品质权重（万分比合计 10000）。
--
-- Recovery: 停服 → 备份副本恢复到新 state 目录 → 配对旧二进制；新增列/
-- 新表与新草稿行，不改既有行。

ALTER TABLE cn35_resource_quest_drafts
    ADD COLUMN initial_power INTEGER NOT NULL DEFAULT 500;
ALTER TABLE cn35_resource_quest_drafts
    ADD COLUMN powerup_rate_bp INTEGER NOT NULL DEFAULT 2500;
ALTER TABLE cn35_resource_quest_drafts
    ADD COLUMN time_limit_sec INTEGER;
ALTER TABLE cn35_resource_quest_drafts
    ADD COLUMN slash_rate_bp INTEGER NOT NULL DEFAULT 1000;
ALTER TABLE cn35_resource_quest_drafts
    ADD COLUMN gun_rate_bp INTEGER NOT NULL DEFAULT 1000;

ALTER TABLE cn35_resource_quest_waves
    ADD COLUMN is_boss INTEGER NOT NULL DEFAULT 0 CHECK (is_boss IN (0,1));
ALTER TABLE cn35_resource_quest_waves
    ADD COLUMN hp INTEGER CHECK (hp IS NULL OR hp > 0);
ALTER TABLE cn35_resource_quest_waves
    ADD COLUMN at INTEGER CHECK (at IS NULL OR at > 0);
ALTER TABLE cn35_resource_quest_waves
    ADD COLUMN kill_sp INTEGER CHECK (kill_sp IS NULL OR kill_sp >= 0);

CREATE TABLE cn35_resource_quest_rune_drops (
    quest_key TEXT PRIMARY KEY REFERENCES cn35_resource_quest_drafts(quest_key) ON DELETE CASCADE,
    mob_chance_bp INTEGER NOT NULL CHECK (mob_chance_bp BETWEEN 0 AND 10000),
    boss_chance_bp INTEGER NOT NULL CHECK (boss_chance_bp BETWEEN 0 AND 10000),
    mob_q1_bp INTEGER NOT NULL CHECK (mob_q1_bp BETWEEN 0 AND 10000),
    mob_q2_bp INTEGER NOT NULL CHECK (mob_q2_bp BETWEEN 0 AND 10000),
    mob_q3_bp INTEGER NOT NULL CHECK (mob_q3_bp BETWEEN 0 AND 10000),
    mob_q4_bp INTEGER NOT NULL CHECK (mob_q4_bp BETWEEN 0 AND 10000),
    boss_q1_bp INTEGER NOT NULL CHECK (boss_q1_bp BETWEEN 0 AND 10000),
    boss_q2_bp INTEGER NOT NULL CHECK (boss_q2_bp BETWEEN 0 AND 10000),
    boss_q3_bp INTEGER NOT NULL CHECK (boss_q3_bp BETWEEN 0 AND 10000),
    boss_q4_bp INTEGER NOT NULL CHECK (boss_q4_bp BETWEEN 0 AND 10000),
    CHECK (mob_q1_bp+mob_q2_bp+mob_q3_bp+mob_q4_bp = 10000),
    CHECK (boss_q1_bp+boss_q2_bp+boss_q3_bp+boss_q4_bp = 10000)
) STRICT;

